-- Early installed schema, frozen independently of migration implementations. No user data.
CREATE TABLE "identities" ( "id" uuid_text NOT NULL PRIMARY KEY, "name" text NOT NULL, "kind" text NOT NULL, "email" text, "model" text, "provider" text, "forge_account" text NOT NULL, CHECK (("kind" = 'human' AND "email" IS NOT NULL AND "email" <> '' AND "model" IS NULL AND "provider" IS NULL) OR ("kind" = 'agent' AND "email" IS NULL AND "model" IS NOT NULL AND "model" <> '' AND "provider" IS NOT NULL AND "provider" <> '')) );
CREATE TABLE "repositories" ( "repository_url" text NOT NULL PRIMARY KEY, CHECK ("repository_url" LIKE 'https://%/%/%' OR "repository_url" LIKE 'http://%/%/%') );
CREATE TABLE "review_contexts" ( "id" uuid_text NOT NULL PRIMARY KEY, "kind" text NOT NULL, "notes_path" text, "git_dir" text, "branch" text, "repository_url" text, "number" integer, "revision" integer NOT NULL, "last_refreshed_at" text, "refreshed_head" text, "refreshed_base" text, "refresh_error" text, "refresh_status" text NOT NULL, "forge_state" text CHECK (forge_state IS NULL OR (kind = 'forge_backed' AND forge_state IN ('open','closed','merged'))), "current_notes_path" text CHECK (current_notes_path IS NULL OR (notes_path IS NOT NULL AND current_notes_path LIKE '/%')), UNIQUE ("notes_path"), UNIQUE ("git_dir", "branch"), UNIQUE ("repository_url", "number"), FOREIGN KEY ("repository_url") REFERENCES "repositories" ("repository_url"), CHECK (("kind" = 'local' AND "notes_path" IS NOT NULL AND "git_dir" IS NULL AND "branch" IS NULL AND "repository_url" IS NULL AND "number" IS NULL AND "refresh_status" = 'never' AND "last_refreshed_at" IS NULL AND "refreshed_head" IS NULL AND "refreshed_base" IS NULL AND "refresh_error" IS NULL) OR ("kind" = 'local' AND "git_dir" IS NOT NULL AND "branch" IS NOT NULL AND "notes_path" IS NULL AND "repository_url" IS NULL AND "number" IS NULL AND "refresh_status" = 'never' AND "last_refreshed_at" IS NULL AND "refreshed_head" IS NULL AND "refreshed_base" IS NULL AND "refresh_error" IS NULL) OR ("kind" = 'forge_backed' AND "repository_url" IS NOT NULL AND "number" > 0 AND "number" IS NOT NULL AND "notes_path" IS NULL AND "git_dir" IS NULL AND "branch" IS NULL)) );
CREATE TABLE "sessions" ( "id" uuid_text NOT NULL PRIMARY KEY, "context_id" uuid_text NOT NULL, "creator_id" uuid_text NOT NULL, "state" text NOT NULL, "base_commit" text, "head_commit" text, "created_at" text NOT NULL, "completed_at" text, "completed_by_id" uuid_text, "outcome" text, "body" text, "forge_review_id" text, "submission_status" text NOT NULL, "submission_error" text, "request_key" text, "request_hash" text, "comparison_kind" text NOT NULL DEFAULT 'legacy' CHECK (comparison_kind IN ('legacy','working','staged','branch','directory','pull_request')), UNIQUE ("id", "context_id"), UNIQUE ("context_id", "request_key"), UNIQUE ("context_id", "forge_review_id"), FOREIGN KEY ("context_id") REFERENCES "review_contexts" ("id"), FOREIGN KEY ("creator_id") REFERENCES "identities" ("id"), FOREIGN KEY ("completed_by_id") REFERENCES "identities" ("id"), CHECK ("state" IN ('active', 'completed')), CHECK (("state" = 'active' AND "completed_at" IS NULL AND "completed_by_id" IS NULL AND "outcome" IS NULL AND "request_key" IS NULL AND "request_hash" IS NULL) OR ("state" = 'completed' AND "completed_at" IS NOT NULL AND "completed_by_id" IS NOT NULL AND "outcome" IS NOT NULL AND "request_key" IS NOT NULL AND "request_hash" IS NOT NULL)) );
CREATE TABLE "threads" ( "id" uuid_text NOT NULL PRIMARY KEY, "context_id" uuid_text NOT NULL, "origin_session_id" uuid_text, "author_id" uuid_text NOT NULL, "anchor_kind" text NOT NULL, "file_path" text, "side" text, "reviewed_commit" text, "start_line" integer, "end_line" integer, "state" text NOT NULL, "resolved_by_id" uuid_text, "resolved_at" text, "updated_by_id" uuid_text, "updated_at" text NOT NULL, "forge_thread_id" text, "outdated" boolean NOT NULL, "selected_text" text, "source_blob_oid" text, "source_content_hash" text, "context_before" text, "context_after" text, "current_path" text, "orphan_reason" text CHECK (orphan_reason IS NULL OR orphan_reason IN ('file_deleted','working_source_changed')), "observed_base" text, "observed_head" text, "observed_outdated" boolean, "observed_path" text, "observed_side" text, "observed_start" integer, "observed_end" integer, "observed_commit" text, "source_kind" text NOT NULL DEFAULT 'legacy' CHECK ((source_kind = 'legacy' AND source_blob_oid IS NULL AND source_content_hash IS NULL AND context_before IS NULL AND context_after IS NULL)  OR (anchor_kind = 'line' AND selected_text IS NOT NULL AND source_content_hash IS NOT NULL AND source_content_hash LIKE 'sha256:%' AND length(source_content_hash) = 71  AND ((source_kind = 'commit' AND source_blob_oid IS NULL AND reviewed_commit IS NOT NULL AND length(reviewed_commit) IN (40,64))  OR (source_kind = 'index_file' AND source_blob_oid IS NOT NULL AND length(source_blob_oid) IN (40,64))  OR (source_kind IN ('working_file','local_file') AND source_blob_oid IS NULL)))) CHECK ((observed_outdated IS NULL AND observed_base IS NULL AND observed_head IS NULL AND observed_path IS NULL AND observed_side IS NULL AND observed_start IS NULL AND observed_end IS NULL AND observed_commit IS NULL) OR (observed_outdated IS NOT NULL AND observed_base IS NOT NULL AND observed_head IS NOT NULL AND ((observed_start IS NULL AND observed_end IS NULL AND observed_side IS NULL AND observed_commit IS NULL) OR (observed_path IS NOT NULL AND observed_start IS NOT NULL AND observed_end IS NOT NULL AND observed_start > 0 AND observed_end >= observed_start AND observed_side IS NOT NULL AND observed_side IN ('old','new') AND observed_commit IS NOT NULL AND length(observed_commit) > 0)))), "source_path" text CHECK (source_path IS NULL OR source_path LIKE '/%'), UNIQUE ("id", "context_id"), UNIQUE ("context_id", "forge_thread_id"), FOREIGN KEY ("context_id") REFERENCES "review_contexts" ("id"), FOREIGN KEY ("author_id") REFERENCES "identities" ("id"), FOREIGN KEY ("resolved_by_id") REFERENCES "identities" ("id"), FOREIGN KEY ("updated_by_id") REFERENCES "identities" ("id"), FOREIGN KEY ("origin_session_id", "context_id") REFERENCES "sessions" ("id", "context_id"), CHECK ("state" IN ('open', 'resolved')), CHECK (("anchor_kind" = 'general' AND "file_path" IS NULL AND "start_line" IS NULL AND "end_line" IS NULL AND "side" IS NULL AND "reviewed_commit" IS NULL) OR ("anchor_kind" = 'file' AND "file_path" IS NOT NULL AND "file_path" <> '' AND "start_line" IS NULL AND "end_line" IS NULL AND "side" IS NULL AND "reviewed_commit" IS NULL) OR ("anchor_kind" = 'line' AND "file_path" IS NOT NULL AND "file_path" <> '' AND "start_line" IS NOT NULL AND "end_line" IS NOT NULL AND "start_line" >= 1 AND "end_line" >= "start_line" AND "side" IS NOT NULL AND "side" IN ('old', 'new') AND "reviewed_commit" IS NOT NULL AND "reviewed_commit" <> '')) );
CREATE TABLE "comments" ( "id" uuid_text NOT NULL PRIMARY KEY, "context_id" uuid_text NOT NULL, "thread_id" uuid_text NOT NULL, "origin_session_id" uuid_text, "author_id" uuid_text NOT NULL, "body" text NOT NULL, "position" integer NOT NULL, "visibility" text NOT NULL, "created_at" text NOT NULL, "updated_at" text NOT NULL, "forge_comment_id" text, "forge_object_kind" text, "forge_review_id" text, "forge_body" text, "forge_updated_at" text, "posting_account_id" text, "posting_state" text NOT NULL, "posting_error" text, "posting_request_key" text, "payload_hash" text, "remote_presence" text NOT NULL, "owner_id" uuid_text REFERENCES identities(id), UNIQUE ("thread_id", "position"), UNIQUE ("context_id", "forge_object_kind", "forge_comment_id"), FOREIGN KEY ("context_id") REFERENCES "review_contexts" ("id"), FOREIGN KEY ("author_id") REFERENCES "identities" ("id"), FOREIGN KEY ("origin_session_id", "context_id") REFERENCES "sessions" ("id", "context_id"), FOREIGN KEY ("thread_id", "context_id") REFERENCES "threads" ("id", "context_id"), CHECK ("position" >= 0), CHECK ("visibility" IN ('draft', 'published')), CHECK (("forge_comment_id" IS NULL AND "forge_object_kind" IS NULL) OR ("forge_comment_id" IS NOT NULL AND "forge_object_kind" IS NOT NULL AND "forge_object_kind" IN ('review_comment', 'conversation_comment', 'review'))), CHECK (("posting_state" IN ('unposted', 'sending', 'confirmed') AND "posting_error" IS NULL) OR ("posting_state" = 'uncertain' AND "posting_error" IS NOT NULL AND "posting_error" <> '')) );
CREATE TABLE "mutation_receipts" ( "context_id" uuid_text NOT NULL, "actor_id" uuid_text NOT NULL, "request_key" text NOT NULL, "method" text NOT NULL, "request_hash" text NOT NULL, "result_json" text NOT NULL, "version" integer NOT NULL, PRIMARY KEY ("context_id", "actor_id", "request_key"), FOREIGN KEY ("context_id") REFERENCES "review_contexts" ("id"), FOREIGN KEY ("actor_id") REFERENCES "identities" ("id"), CHECK ("request_key" <> ''), CHECK ("method" <> ''), CHECK ("request_hash" <> ''), CHECK ("version" > 0) );
CREATE TABLE "note_promotions" ( "source_comment_id" uuid_text NOT NULL, "target_session_id" uuid_text NOT NULL, "target_comment_id" uuid_text UNIQUE, "request_key" text NOT NULL, "payload_hash" text NOT NULL, PRIMARY KEY ("source_comment_id", "target_session_id"), FOREIGN KEY ("target_session_id") REFERENCES "sessions" ("id"), FOREIGN KEY ("target_comment_id") REFERENCES "comments" ("id") ON DELETE SET NULL );
CREATE TABLE "workspace_paths" ( "context_id" uuid_text NOT NULL, "path" text NOT NULL, PRIMARY KEY ("context_id", "path"), FOREIGN KEY ("context_id") REFERENCES "review_contexts" ("id") );
CREATE TABLE "seaql_migrations" ( "version" varchar NOT NULL PRIMARY KEY, "applied_at" integer NOT NULL );
CREATE UNIQUE INDEX "agent_identity_key" ON "identities" ("name", "model", "provider") WHERE "kind" = 'agent';
CREATE UNIQUE INDEX "forge_account_identity" ON "identities" ("forge_account") WHERE "forge_account" <> '';
CREATE UNIQUE INDEX "human_identity_key" ON "identities" ("email", "forge_account") WHERE "kind" = 'human';
CREATE UNIQUE INDEX "one_active_session" ON "sessions" ("context_id") WHERE "state" = 'active';
